#!/usr/bin/env python3
"""X-02: materialize and query a complete learned-structure provenance chain."""
from __future__ import annotations
import hashlib,importlib.metadata,json,platform
from datetime import datetime,timezone
from pathlib import Path
import duckdb,pyarrow as pa,pyarrow.parquet as pq
P=Path(__file__).resolve().parent;OUT=P/'output';ROOT=P.parents[1]
def load(rel):p=ROOT/rel;return p,json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 OUT.mkdir(parents=True,exist_ok=True);gp,grecs=load('poc/graph-02/output/results.json');i3p,i3=load('poc/ind-03/output/results.json');h1p,h1=load('poc/hyp-01/output/results.json');h2p,h2=load('poc/hyp-02/output/results.json');h3p,h3=load('poc/hyp-03/output/results.json');h4p,h4=load('poc/hyp-04/output/results.json');s5p,s5=load('poc/sem-05/output/results.json')
 selected=[next(x for x in grecs if x['annotation_type']==t) for t in ['nlp-01','nlp-02','sem-01']];pattern={'pattern_id':'PATTERN-PROVENANCE-CHAIN-01','induction_engine':'IND-03-compatible anonymous recurrent subgraph','schema':['Pattern→Occurrence','Occurrence→ExternalAnalysis','ExternalAnalysis→Span'],'anonymous_variables':['?occurrence','?analysis','?span'],'source_pattern_id':i3['pattern']['id']}
 nodes=[{'id':pattern['pattern_id'],'kind':'pattern','payload':json.dumps(pattern)}];edges=[];occurrences=[]
 for n,a in enumerate(selected,1):
  oid=f'OCC-{n:02d}';sid=f'SPAN-{n:02d}';occ={'occurrence_id':oid,'analysis_id':a['id'],'producer':a['producer'],'producer_version':a['producer_version'],'span':a['spans'][0],'source_artifact':a['source_artifact'],'source_selector':a['source_selector'],'raw_value_sha256':a['raw_value_sha256'],'alternatives':json.loads(a['alternatives_json']) if isinstance(a['alternatives_json'],str) else a['alternatives_json']};occurrences.append(occ);nodes +=[{'id':oid,'kind':'occurrence','payload':json.dumps({'binding':{'?occurrence':oid,'?analysis':a['id'],'?span':sid}})},{'id':a['id'],'kind':'external_analysis','payload':json.dumps({'producer':a['producer'],'version':a['producer_version'],'artifact':a['source_artifact'],'selector':a['source_selector'],'hash':a['raw_value_sha256']})},{'id':sid,'kind':'span','payload':json.dumps(a['spans'][0])}];edges +=[{'source':pattern['pattern_id'],'target':oid,'relation':'has-occurrence','provenance':'IND-03 schema match'},{'source':oid,'target':a['id'],'relation':'supported-by-analysis','provenance':'GRAPH-02 annotation id'},{'source':a['id'],'target':sid,'relation':'anchored-at-span','provenance':'GRAPH-02 producer-native span'}]
 cross=next(e for e in s5['index']['edges'] if e['edge_id']=='e4');nodes +=[{'id':cross['source'],'kind':'form','payload':'{}'},{'id':cross['target'],'kind':'phonological','payload':'{}'}];edges.append({'source':cross['source'],'target':cross['target'],'relation':cross['relation'],'provenance':cross['provenance']})
 selection_events=h3['selection_events'];assert len(selection_events)>=2;for_rank=[{'context':k,'winner':v,'ranking':h4['rankings'][k]} for k,v in h4['winners'].items()];contradictions=h2['conflicts'];alternatives=[{'hypothesis_id':x['hypothesis_id'],'entries':json.loads(h1['evidence_snapshot']['entries_json'])} for x in h1['hypothesis_versions']]
 for event in selection_events:nodes.append({'id':event['selection_event_id'],'kind':'dated_selection','payload':json.dumps(event)});edges.append({'source':event['selection_event_id'],'target':event['hypothesis_id'],'relation':'selected-hypothesis','provenance':event['snapshot_id']})
 pq.write_table(pa.Table.from_pylist(nodes),OUT/'provenance-nodes.parquet',compression='zstd');pq.write_table(pa.Table.from_pylist(edges),OUT/'provenance-edges.parquet',compression='zstd');db=OUT/'x-02.duckdb';
 if db.exists():db.unlink()
 con=duckdb.connect(str(db));con.execute('CREATE TABLE nodes AS SELECT * FROM read_parquet(?)',[str((OUT/'provenance-nodes.parquet').resolve())]);con.execute('CREATE TABLE edges AS SELECT * FROM read_parquet(?)',[str((OUT/'provenance-edges.parquet').resolve())]);paths=con.execute("""SELECT p.source pattern,p.target occurrence,a.target analysis,s.target span FROM edges p JOIN edges a ON p.target=a.source JOIN edges s ON a.target=s.source JOIN nodes o ON o.id=p.target WHERE p.relation='has-occurrence' AND a.relation='supported-by-analysis' AND s.relation='anchored-at-span' ORDER BY occurrence""").fetchall();producer_count=con.execute("SELECT count(DISTINCT json_extract_string(payload,'$.producer')) FROM nodes WHERE kind='external_analysis'").fetchone()[0];con.close()
 validations={'pattern_to_span_paths_complete':len(paths)==3 and all(all(x for x in path) for path in paths),'at_least_two_external_producers':producer_count>=2 and {o['producer'] for o in occurrences}>={'ACE+ERG','Epitran'},'producer_versions_present':all(o['producer_version'] for o in occurrences),'source_hashes_and_selectors_present':all(len(o['raw_value_sha256'])==64 and o['source_selector'] for o in occurrences),'cross_representation_relation_present':cross['source'].startswith('form:') and cross['target'].startswith('phon:') and cross['provenance'],'alternatives_preserved':len(alternatives)>=4,'justification_snapshots_preserved':all(e['snapshot_id'] for e in selection_events),'contradictions_explicit':len(contradictions)>=1,'dated_selection_changed':selection_events[0]['hypothesis_id']!=selection_events[1]['hypothesis_id'] and selection_events[0]['selected_at']<selection_events[1]['selected_at'],'contextual_ranking_changes':len({x['winner'] for x in for_rank})==3,'induced_pattern_linked':pattern['source_pattern_id']=='Pattern_Recurrent_001'};assert all(validations.values()),validations
 source_paths=[gp,i3p,h1p,h2p,h3p,h4p,s5p];result={'pattern':pattern,'occurrences':occurrences,'inspectable_paths':[{'pattern':x[0],'occurrence':x[1],'analysis':x[2],'span':x[3]} for x in paths],'cross_representation_relation':cross,'alternatives':alternatives,'contradictions':contradictions,'selection_events':selection_events,'contextual_rankings':for_rank,'source_artifacts':{str(p.relative_to(ROOT)):sha(p) for p in source_paths},'validations':validations};(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(OUT/'summary.json').write_text(json.dumps({'patterns':1,'occurrences':len(occurrences),'external_producers':producer_count,'inspectable_paths':len(paths),'cross_representation_relations':1,'dated_selection_events':len(selection_events),'contradictions':len(contradictions),'verdict':'GO_END_TO_END_LEARNED_STRUCTURE_PROVENANCE'},indent=2)+'\n');(OUT/'versions-and-parameters.json').write_text(json.dumps({'generated_at':datetime.now(timezone.utc).isoformat(),'platform':platform.platform(),'duckdb':importlib.metadata.version('duckdb'),'pyarrow':importlib.metadata.version('pyarrow'),'path_query':'Pattern -> occurrence -> external analysis -> span'},indent=2)+'\n');print('X-02: pattern-to-analysis-to-span provenance, alternatives and dated reranking verified; GO')
if __name__=='__main__':main()
